104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        if (normalizedTelephone == null) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
112	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.CONFLICT);
117	        }
118	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
119	        List<Owner> householdMembers =
120	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
121	        if (!sharesHousehold && !householdMembers.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        owner.setTelephone(normalizedTelephone);
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
131	        if (sharesHousehold && !householdMembers.isEmpty()) {
132	            String householdId = householdId(owner.getLastName(), normalizedAddress);
133	            owner.setHouseholdId(householdId);
134	            for (Owner member : householdMembers) {
135	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
136	                    member.setHouseholdId(householdId);
137	                    this.clinicService.saveOwner(member);
138	                }
139	            }
140	        }
141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
