232	
233	    /**
234	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
235	     * stripped. When a leading {@code '+'} and country code are present they are kept;
236	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
237	     * is dropped from the national digits. The result must be a {@code '+'} followed
238	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
239	     * is returned to signal a bad request.
240	     */
241	    /**
242	     * Build the customer code for a newly created owner, formatted
243	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
244	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
245	     * sequence equal to one more than the current number of owners.
246	     */
247	    private String nextCustomerCode(String lastName) {
248	        String prefix = lastName == null ? "" : lastName;
249	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(Locale.ROOT);
250	        int sequence = this.clinicService.findAllOwners().size() + 1;
251	        return String.format("%s-%04d", prefix, sequence);
252	    }
253	
254	    /**
255	     * Find the existing owners that already belong to the same household as the given
256	     * last name and address, i.e. those sharing both fields. Both are compared
257	     * case-insensitively after collapsing runs of whitespace to a single space and
258	     * trimming the ends.
259	     */
260	    private List<Owner> findHouseholdMembers(String lastName, String address) {
261	        String normalizedLastName = normalizeForHousehold(lastName);
262	        String normalizedAddress = normalizeForHousehold(address);
263	        return this.clinicService.findAllOwners().stream()
264	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
265	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
266	            .toList();
267	    }
268	
269	    /**
270	     * Build a stable identifier shared by all owners of one household. It is derived
271	     * deterministically from the normalized last name and address, so every owner at
272	     * the same household resolves to the same value regardless of creation order.
273	     */
274	    private String householdId(String lastName, String address) {
275	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
276	        try {
277	            byte[] digest = MessageDigest.getInstance("SHA-256")
278	                .digest(key.getBytes(StandardCharsets.UTF_8));
279	            StringBuilder sb = new StringBuilder();
280	            for (int i = 0; i < 6; i++) {
281	                sb.append(String.format("%02X", digest[i]));
282	            }
283	            return "HH-" + sb;
284	        }
285	        catch (NoSuchAlgorithmException e) {
286	            throw new IllegalStateException(e);
287	        }
288	    }
289	
290	    private String normalizeForHousehold(String value) {
291	        if (value == null) {
292	            return "";
293	        }
294	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
295	    }
296	
297	    private String normalizeTelephone(String telephone) {
298	        if (telephone == null) {
299	            return null;
300	        }
301	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
302	        String digits;
303	        if (cleaned.startsWith("+")) {
304	            digits = cleaned.substring(1);
305	        } else {
306	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
307	            digits = "61" + national;
308	        }
309	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
315	        Owner owner = this.clinicService.findOwnerById(ownerId);
316	        if (owner != null) {
317	            Pet pet = owner.getPet(petId);
318	            if (pet != null) {
319	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	}
